// Everything here must be DETERMINISTIC: the island's output is byte-diffed
// against real Node, so nothing may depend on the clock, the pid or a random
// path. The fs half works inside a fresh mkdtemp directory and prints only
// CONTENT and SHAPE - never the generated path, never an mtime.
//
// Two deliberate omissions, both honest fences rather than oversights:
//   - md5 is not exercised. The Rust runtime's digests are ring's, which does
//     not carry md5, so the island refuses it out loud. Node would answer.
//   - no compressed BYTES are printed. The Rust lane deflates with flate2 at
//     its default level and Node with zlib at its own, so the compressed form
//     is allowed to differ; what must agree is that a roundtrip returns the
//     original bytes, which is what the zlib section checks.
const fs = require("fs");
const os = require("os");
const path = require("path");
const crypto = require("crypto");
const zlib = require("zlib");

const lines = [];
const push = (label, value) => lines.push(label + " " + value);

// A directory per run, removed at the end, so repeated runs cannot see each
// other and the differential never depends on what was left behind.
function withTempDir(body) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "scriptc-iozoo-"));
  try {
    return body(dir);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

function filesystem() {
  withTempDir((dir) => {
    const file = path.join(dir, "note.txt");
    fs.writeFileSync(file, "hello island\n");
    fs.appendFileSync(file, "second line\n");

    push("fs:read", JSON.stringify(fs.readFileSync(file, "utf8")));
    push("fs:bytes", fs.readFileSync(file).length);
    push("fs:exists", [fs.existsSync(file), fs.existsSync(path.join(dir, "nope"))].join(","));

    const stats = fs.statSync(file);
    push("fs:stat", [stats.isFile(), stats.isDirectory(), stats.isSymbolicLink(), stats.size].join(","));
    push("fs:stat-dir", [fs.statSync(dir).isDirectory(), fs.statSync(dir).isFile()].join(","));
    // The absent-file escape hatch: throwIfNoEntry:false is only reachable if
    // the host bridge reports a Node-shaped ENOENT, so this pins the code.
    push("fs:stat-missing", fs.statSync(path.join(dir, "nope"), { throwIfNoEntry: false }));

    fs.mkdirSync(path.join(dir, "nested", "deep"), { recursive: true });
    fs.writeFileSync(path.join(dir, "nested", "b.txt"), "b");
    push("fs:readdir", fs.readdirSync(dir).sort().join("|"));
    const entries = fs
      .readdirSync(dir, { withFileTypes: true })
      .map((entry) => entry.name + ":" + (entry.isDirectory() ? "dir" : entry.isFile() ? "file" : "other"))
      .sort();
    push("fs:dirents", entries.join("|"));

    fs.copyFileSync(file, path.join(dir, "copy.txt"));
    push("fs:copy", JSON.stringify(fs.readFileSync(path.join(dir, "copy.txt"), "utf8")));
    fs.renameSync(path.join(dir, "copy.txt"), path.join(dir, "moved.txt"));
    push("fs:rename", [fs.existsSync(path.join(dir, "copy.txt")), fs.existsSync(path.join(dir, "moved.txt"))].join(","));
    fs.unlinkSync(path.join(dir, "moved.txt"));
    push("fs:unlink", fs.existsSync(path.join(dir, "moved.txt")));

    push("fs:access", fs.accessSync(file, fs.constants.R_OK) === undefined);
    // realpath resolves the tmpdir itself, so compare against a realpath of
    // the directory rather than the (possibly symlinked) path we built.
    push("fs:realpath", fs.realpathSync(file) === path.join(fs.realpathSync(dir), "note.txt"));

    let code = "";
    try {
      fs.readFileSync(path.join(dir, "nope"));
    } catch (error) {
      code = error.code;
    }
    push("fs:enoent", code);

    push("fs:constants", [
      fs.constants.F_OK, fs.constants.R_OK, fs.constants.W_OK, fs.constants.X_OK,
    ].join(","));
  });
}

function digests() {
  const data = Buffer.from("the quick brown fox");
  for (const algorithm of ["sha1", "sha256", "sha512"]) {
    push("hash:" + algorithm, crypto.createHash(algorithm).update(data).digest("hex"));
  }
  // Chained updates must fold into one digest, not several.
  push(
    "hash:chained",
    crypto.createHash("sha256").update("the ").update("quick ").update("brown fox").digest("hex"),
  );
  push("hash:base64", crypto.createHash("sha256").update(data).digest("base64"));
  for (const algorithm of ["sha1", "sha256", "sha512"]) {
    push("hmac:" + algorithm, crypto.createHmac(algorithm, "key").update(data).digest("hex"));
  }
  push("hmac:buffer-key", crypto.createHmac("sha256", Buffer.from("key")).update(data).digest("hex"));
  push("random:shape", [
    crypto.randomBytes === undefined ? "absent" : typeof crypto.randomBytes,
    crypto.timingSafeEqual(Buffer.from("ab"), Buffer.from("ab")),
    crypto.timingSafeEqual(Buffer.from("ab"), Buffer.from("ac")),
  ].join(","));
}

function compression() {
  const text = "island zlib roundtrip ".repeat(16);
  const source = Buffer.from(text);
  const pairs = [
    ["gzip", zlib.gzipSync, zlib.gunzipSync],
    ["deflate", zlib.deflateSync, zlib.inflateSync],
    ["deflateRaw", zlib.deflateRawSync, zlib.inflateRawSync],
  ];
  for (const [name, compress, expand] of pairs) {
    const packed = compress(source);
    push("zlib:" + name, [
      Buffer.isBuffer(packed),
      packed.length < source.length,
      expand(packed).toString("utf8") === text,
    ].join(","));
  }
  // unzip sniffs the framing, so it must expand both gzip and zlib streams.
  push("zlib:unzip", [
    zlib.unzipSync(zlib.gzipSync(source)).toString("utf8") === text,
    zlib.unzipSync(zlib.deflateSync(source)).toString("utf8") === text,
  ].join(","));
  push("zlib:empty", zlib.gunzipSync(zlib.gzipSync(Buffer.alloc(0))).length);
  let code = "";
  try {
    zlib.gunzipSync(Buffer.from("not a gzip stream at all"));
  } catch (error) {
    code = typeof error.code === "string" ? "coded" : "uncoded";
  }
  push("zlib:garbage", code);
}

function system() {
  push("os:platform", os.platform());
  push("os:arch", os.arch());
  push("os:type", os.type());
  push("os:endianness", os.endianness());
  push("os:eol", JSON.stringify(os.EOL));
  push("os:tmpdir", os.tmpdir());
  push("os:homedir", os.homedir());
  // hostname and the user record vary by machine; only their SHAPE is stable.
  push("os:hostname-shape", typeof os.hostname() === "string" && os.hostname().length > 0);
  const user = os.userInfo();
  push("os:user-shape", [typeof user.uid, typeof user.gid, typeof user.username].join(","));
  push("os:signals", [os.constants.signals.SIGINT, os.constants.signals.SIGTERM].join(","));
  // The inert half: values Node reads from the kernel that the island answers
  // empty-but-typed on purpose. Only the TYPE can agree, so only the type is
  // compared - a count or an uptime would differ by design, not by defect.
  push("os:inert", [
    Array.isArray(os.cpus()), os.loadavg().length, typeof os.uptime(), typeof os.totalmem(),
  ].join(","));
}

module.exports.report = function report() {
  lines.length = 0;
  filesystem();
  digests();
  compression();
  system();
  return lines.join("\n");
};

// fs/promises is derived from the same synchronous host calls - the island has
// no thread pool - so awaiting them must still produce Node's answers.
module.exports.promised = async function promised() {
  const fsp = require("fs/promises");
  const dir = await fsp.mkdtemp(path.join(os.tmpdir(), "scriptc-iozoo-p-"));
  try {
    const file = path.join(dir, "async.txt");
    await fsp.writeFile(file, "promised\n");
    const read = await fsp.readFile(file, "utf8");
    const stats = await fsp.stat(file);
    const names = await fsp.readdir(dir);
    return ["promises:read " + JSON.stringify(read), "promises:size " + stats.size, "promises:readdir " + names.join("|")].join("\n");
  } finally {
    await fsp.rm(dir, { recursive: true, force: true });
  }
};
